/* From Uiverse.io by JaydipPrajapati1910 - Tags: button, hover effect, buttons */
.__UIV_SCOPE__ .wrapper {
  display: inline-flex;
  list-style: none;
  height: 120px;
  width: 100%;
  padding-top: 40px;
  font-family: "Poppins", sans-serif;
  justify-content: center;
}

.__UIV_SCOPE__ .wrapper .icon {
  position: relative;
  background: #fff;
  border-radius: 50%;
  margin: 10px;
  width: 50px;
  height: 50px;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  box-shadow: 0 10px 10px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.__UIV_SCOPE__ .wrapper .tooltip {
  position: absolute;
  top: 0;
  font-size: 14px;
  background: #fff;
  color: #fff;
  padding: 5px 8px;
  border-radius: 5px;
  box-shadow: 0 10px 10px rgba(0, 0, 0, 0.1);
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.__UIV_SCOPE__ .wrapper .tooltip::before {
  position: absolute;
  content: "";
  height: 8px;
  width: 8px;
  background: #fff;
  bottom: -3px;
  left: 50%;
  transform: translate(-50%) rotate(45deg);
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.__UIV_SCOPE__ .wrapper .icon:hover .tooltip {
  top: -45px;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.__UIV_SCOPE__ .wrapper .icon:hover span,
.__UIV_SCOPE__ .wrapper .icon:hover .tooltip {
  text-shadow: 0px -1px 0px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .wrapper svg {
  fill: green;
}

.__UIV_SCOPE__ .wrapper span:hover,
.__UIV_SCOPE__ .wrapper svg:hover,
.__UIV_SCOPE__ .wrapper .black:hover,
.__UIV_SCOPE__ .wrapper .black:hover .tooltip,
.__UIV_SCOPE__ .wrapper .black:hover .tooltip::before {
  background: #222;
  color: white;
  fill: white;
}
